from distutils.command.build_ext import build_ext
from distutils.errors import CCompilerError, DistutilsExecError, DistutilsPlatformError
import sys
from setuptools import setup, Extension
build_errors = (
 CCompilerError, DistutilsExecError, DistutilsPlatformError)
if sys.platform == b'win32' and sys.version_info > (2, 6):
    build_errors += (IOError,)

class BuildError(Exception):
    pass


class optional_build_ext(build_ext):

    def run(self):
        try:
            build_ext.run(self)
        except DistutilsPlatformError:
            raise BuildError()

        return

    def build_extension(self, ext):
        try:
            build_ext.build_extension(self, ext)
        except build_errors as be:
            raise BuildError(be)
        except ValueError as ve:
            if b"'path'" in str(sys.exc_info()[1]):
                raise BuildError(ve)
            raise

        return


VERSION = eval(open(b'cbor/VERSION.py', b'rb').read())
setup_options = dict(name=b'cbor', version=VERSION, description=b'RFC 7049 - Concise Binary Object Representation', long_description=b"\nAn implementation of RFC 7049 - Concise Binary Object Representation (CBOR).\n\nCBOR is comparable to JSON, has a superset of JSON's ability, but serializes to a binary format which is smaller and faster to generate and parse.\n\nThe two primary functions are cbor.loads() and cbor.dumps().\n\nThis library includes a C implementation which runs 3-5 times faster than the Python standard library's C-accelerated implementanion of JSON. This is also includes a 100% Python implementation.\n", author=b'Brian Olson', author_email=b'bolson@bolson.org', url=b'https://bitbucket.org/bodhisnarkva/cbor', packages=[
 b'cbor'], package_dir={b'cbor': b'cbor'}, ext_modules=[
 Extension(b'cbor._cbor', include_dirs=[
  b'c/'], sources=[
  b'c/cbormodule.c'], headers=[
  b'c/cbor.h'])], license=b'Apache', classifiers=[
 40, 
 41, 
 42, 
 43, 
 44, 
 45, 
 46, 
 47, 
 48], cmdclass={b'build_ext': optional_build_ext})

def main():
    is_jython = b'java' in sys.platform
    is_pypy = hasattr(sys, b'pypy_translation_info')
    if is_jython or is_pypy:
        del setup_options[b'ext_modules']
    try:
        setup(**setup_options)
    except BuildError as be:
        sys.stderr.write(b'\nBUILD ERROR:\n  %s\nRETRYING WITHOUT C EXTENSIONS\n' % (be,))
        del setup_options[b'ext_modules']
        setup(**setup_options)

    return


if __name__ == b'__main__':
    main()
